import{_ as o,l as n,o as a,c as l,v as t,p as E,x as i,d as s,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"实验经济学方法","description":"","frontmatter":{"title":"实验经济学方法","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/experimental-methods.md","filePath":"econ/experimental-methods.md","lastUpdated":1789023840000}'),c={name:"econ/experimental-methods.md"};function h(m,e,A,B,_,u){const r=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="实验经济学方法" tabindex="-1">实验经济学方法 <a class="header-anchor" href="#实验经济学方法" aria-label="Permalink to &quot;实验经济学方法&quot;">​</a></h1><div class="epigraph"><p>用货币诱导价值，把理论的 $u$ 变成可操纵的支付；内部有效不等于现场有效，但没有内部有效就没有机制证据。</p><footer>—— Smith, Experimental Economics: Induced Value Theory, 1976；Smith, Microeconomic Systems as an Experimental Science, AER 1982</footer></div><p><a href="/econ/belief-updating-biases">上一课</a>堆叠了实验室风格的偏差。本课缺口是方法：如何把这些主张从故事变成可复制的证据，以及证据能外推多远。行为单元在此收束，下一单元把偏差放进资产市场理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>现场价格同时含偏好、信念、约束和均衡。拒绝 <a href="/econ/emh">EMH</a> 或拒绝欧拉，无法直接读出「因为损失厌恶」。Vernon Smith 的诱导价值：用货币支付诱导出实验者想要的价值和信息结构，从而隔离机制。最后通牒、杯子、校准测验，都依赖这一逻辑。缺口是标明识别与外推，而不是再做一个偏差清单。</p><p><span class="marginnote">内部有效：在所设环境下因果清楚。外部有效：对现场仍成立。两者冲突时，本栏补层先要内部有效，再谈加总。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计要素：随机分配、匿名、真实支付、重复与学习、控制信息。市场实验看能否收敛到竞争均衡；个人实验看是否偏离 vNM。本课不教软件。对照：自然实验与田野实验（Ashraf–Karlan–Yin 的承诺账户、Madrian–Shea 的默认）牺牲部分控制，换取外部有效。行为金融理论课将混合使用：实验室给零件，价格与持仓给加总。</p>',8)),(a(),E(d,null,{default:i(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIELD%5B%22%E7%8E%B0%E5%9C%BA%3A%20%E5%81%8F%E5%A5%BD%E4%BF%A1%E5%BF%B5%E7%BA%A6%E6%9D%9F%E7%BC%A0%E5%9C%A8%E4%B8%80%E8%B5%B7%22%5D%20--%3E%20IND%5B%22%E8%AF%B1%E5%AF%BC%E4%BB%B7%E5%80%BC%3A%20%E9%9A%94%E7%A6%BB%E6%9C%BA%E5%88%B6%22%5D%0A%20%20IND%20--%3E%20INT%5B%22%E5%86%85%E9%83%A8%E6%9C%89%E6%95%88%22%5D%0A%20%20INT%20--%3E%20EXT%5B%22%E5%A4%96%E6%8E%A8%3A%20%E7%94%B0%E9%87%8E%E4%B8%8E%E8%87%AA%E7%84%B6%E5%AE%9E%E9%AA%8C%22%5D%0A%20%20EXT%20--%3E%20MKT%5B%22%E5%90%8E%E5%8D%95%E5%85%83%3A%20%E5%99%AA%E5%A3%B0%E4%B8%8E%E5%A5%97%E5%88%A9%E9%99%90%E5%88%B6%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是控制。诱导价值把<a href="/econ/preference-choice">偏好</a>的 \\(X\\) 变成实验者设定的支付表；若仍出现禀赋效应，就不能把原因推给「未知的真实 u」。信息集被写在说明书里，过度自信就可以对照客观精度。重复博弈看偏差是否被套利或学习消灭——这正是下一课 DSSW 要问的市场问题的实验室前身。</p><p>支付过小会把选择变成廉价交谈；支付过大受预算限制。风险态度被实验室财富与「房子钱」账户污染——心理账户在方法上是威胁。</p><p>Smith 的市场实验表明：诱导价值下双拍卖可以收敛到竞争均衡，即使被试不会解瓦尔拉斯。因此「人有偏差」与「市场能加总」不是同一命题——DSSW 问的正是加总何时失败。内部有效要求随机分配与真实支付；外部有效要求现场的约束也在。401(k) 默认是田野，杯子是实验室，PEAD 是价格。三层证据要分开标，不能用一层否证另一层的全部。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>学生样本、低利害、抽象框架，限制外推到家庭组合与机构套利。本课不宣称实验室否证了 <a href="/econ/expected-utility">vNM</a> 在所有现场的用途；主干定价核仍用它。补层的态度是：实验室给出可靠零件，市场理论问零件能否在套利下存活。</p><p>后课默认：噪声交易者不是实验室被试的别名，而要有一个风险与资本的均衡模型。</p><p>诱导价值把 \\(u\\) 变成可操纵支付；内部有效先于外推。市场能收敛与个人有偏差不是同一命题。</p><p>实验室给零件，田野给外部有效，价格残差给加总。下一单元问零件在套利下能否存活。</p><p><span class="marginnote">实验室收敛不能推出现场无偏差；现场残差也不能单独指认心理学零件。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>诱导价值隔离机制；内部有效先于外推。</li><li>田野补外部有效；价格残差单独不能指认心理学。</li><li>行为单元到此结束；下一单元问偏差如何进入资产价格。</li><li>支付过小变成廉价交谈。</li><li>房子钱账户会污染风险态度。</li><li>出处：Smith 1976, <em>AER</em> 1982。</li></ul>',12))])}const T=o(c,[["render",h]]);export{S as __pageData,T as default};
